class Solution:
    def minTime(self, n: int, edges: List[List[int]], k: int) -> int:
        par = list(range(n))
        def find(x):
            while par[x] != x:
                par[x] = par[par[x]]
                x = par[x]
            return x
        comp, ans = n, 0
        edges.sort(key=lambda e: -e[2])
        i = 0
        while i < len(edges):
            t = edges[i][2]
            if comp >= k:
                ans = t
            while i < len(edges) and edges[i][2] == t:
                ru, rv = find(edges[i][0]), find(edges[i][1])
                if ru != rv:
                    par[ru] = rv
                    comp -= 1
                i += 1
        if comp >= k:
            ans = 0
        return ans

