        int lo = 0, hi = 0;
        for (auto& e : edges) hi = max(hi, e[2]);
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (ok(edges, n, k, mid)) hi = mid;
            else lo = mid + 1;
